def get_valid_moves(pos, n):
    r, c = divmod(pos, n)
    moves = [
        (r + 2, c + 1), (r + 2, c - 1), (r - 2, c + 1), (r - 2, c - 1),
        (r + 1, c + 2), (r + 1, c - 2), (r - 1, c + 2), (r - 1, c - 2)
    ]
    valid_moves = []
    for nr, nc in moves:
        if 0 <= nr < n and 0 <= nc < n:
            valid_moves.append(nr * n + nc)
    return valid_moves

def solve_knights_tour(n):
    board = [-1] * (n * n)

    def get_degree(pos, visited):
        moves = get_valid_moves(pos, n)
        degree = 0
        for move in moves:
            if move not in visited:
                degree += 1
        return degree

    def backtrack(curr_pos, visited_order):
        if len(visited_order) == n * n:
            return visited_order

        moves = get_valid_moves(curr_pos, n)
        unvisited_moves = [m for m in moves if m not in visited_order]

        # Warnsdorff's rule: sort by degree
        unvisited_moves.sort(key=lambda m: get_degree(m, set(visited_order)))

        for next_pos in unvisited_moves:
            visited_order.append(next_pos)
            result = backtrack(next_pos, visited_order)
            if result:
                return result
            visited_order.pop()
        return None

    start_pos = 0
    return backtrack(start_pos, [start_pos])

