def is_valid_tour(tour, n):
    if len(tour) != n * n:
        return False
    if len(set(tour)) != n * n:
        return False
    if tour[0] != 0:
        return False

    for i in range(len(tour) - 1):
        curr = tour[i]
        nxt = tour[i+1]
        r1, c1 = divmod(curr, n)
        r2, c2 = divmod(nxt, n)
        dr = abs(r1 - r2)
        dc = abs(c1 - c2)
        if not ((dr == 1 and dc == 2) or (dr == 2 and dc == 1)):
            return False
    return True

